using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class Fibre116Checks{
 public static void Legacy(){int exit=0;try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string folder="Assets/Imported116-legacy";Check(!AssetDatabase.IsValidFolder(folder),"fresh legacy evidence");AssetDatabase.CreateFolder("Assets","Imported116-legacy");var parent=new GameObject("legacy");var prefabs=new Dictionary<string,GameObject>();LegacySmallProps114.Build(Path.Combine(Root,"Input114-after"),folder,parent.transform,Shader.Find("MapSharedProps/Lit"),prefabs);Check(prefabs.Count==43&&!prefabs.ContainsKey("obsidian"),"old source reader 43");foreach(var item in prefabs){var current=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported116/small-"+item.Key+".prefab");Check(ColliderSnapshot109.MeshHash(current.GetComponent<MeshFilter>().sharedMesh)==ColliderSnapshot109.MeshHash(item.Value.GetComponent<MeshFilter>().sharedMesh),"legacy geometry");int count=current.GetComponentsInChildren<Collider>(true).Length;Check(count==item.Value.GetComponentsInChildren<Collider>(true).Length,"legacy collider count");if(count>0)Check(ColliderSnapshot109.Capture(current)==ColliderSnapshot109.Capture(item.Value),"legacy collider");}UnityEngine.Object.DestroyImmediate(parent);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Root,"Evidence116Studio/legacy.json"),"{\"pass\":true,\"prefabs\":43,\"sourceControlFlowOnly\":true,\"oldBinaryExecuted\":false}");}catch(Exception e){Debug.LogException(e);exit=1;}finally{EditorApplication.Exit(exit);}}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));
 [Serializable]public class Row{public string mode,light;public float before,after;}[Serializable]public class Report{public bool pass;public int prefabs;public Row[] rows;public string[] limits;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence116Studio");Directory.CreateDirectory(output);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string folder="Assets/Imported116";Check(!AssetDatabase.IsValidFolder(folder),"fresh import");AssetDatabase.CreateFolder("Assets","Imported116");var parent=new GameObject("formal");var prefabs=new Dictionary<string,GameObject>();SmallPropsV1.Build(Path.Combine(Root,"Input114-after"),folder,parent.transform,Shader.Find("MapSharedProps/Lit"),prefabs);Check(prefabs.Count==44,"44 formal prefabs");UnityEngine.Object.DestroyImmediate(parent);
  foreach(var item in prefabs){var before=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported115-default/small-"+item.Key+".prefab");Check(before,"baseline");var after=item.Value;Check(ColliderSnapshot109.MeshHash(before.GetComponent<MeshFilter>().sharedMesh)==ColliderSnapshot109.MeshHash(after.GetComponent<MeshFilter>().sharedMesh),"mesh "+item.Key);var bm=before.GetComponent<MeshFilter>().sharedMesh;var am=after.GetComponent<MeshFilter>().sharedMesh;Check(bm.uv.SequenceEqual(am.uv)&&bm.normals.SequenceEqual(am.normals)&&bm.colors.SequenceEqual(am.colors),"surface data "+item.Key);int count=before.GetComponentsInChildren<Collider>(true).Length;Check(count==after.GetComponentsInChildren<Collider>(true).Length,"collider count");if(count>0)Check(ColliderSnapshot109.Capture(before)==ColliderSnapshot109.Capture(after),"actual collider");}
  var objects=new List<GameObject>();foreach(var id in new[]{"coiledrope","tiedsack"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[id]);o.transform.position=new Vector3(id=="coiledrope"?-.48f:.48f,.05f,0);objects.Add(o);}
  var camera=new GameObject("offscreen").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.transform.position=new Vector3(1.7f,2.2f,-2.7f);camera.transform.LookAt(new Vector3(0,.25f,0));camera.fieldOfView=35;camera.aspect=4f/3;camera.GetUniversalAdditionalCameraData().renderPostProcessing=false;
  RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;
  var local=new GameObject("diagnostic local").AddComponent<Light>();local.transform.position=new Vector3(-.4f,2,-.5f);local.transform.LookAt(new Vector3(0,.15f,0));local.color=new Color(1,.65f,.3f);local.intensity=4;local.range=6;local.spotAngle=70;local.innerSpotAngle=45;local.shadowStrength=1;
  var sun=new GameObject("diagnostic sun").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(45,30,0);sun.intensity=1;sun.enabled=false;
  var blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.transform.position=new Vector3(-.2f,1,-.25f);blocker.transform.localScale=new Vector3(2,.1f,2);blocker.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.ShadowsOnly;blocker.SetActive(false);
  var rows=new List<Row>();foreach(int mode in new[]{0,2}){var rp=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset"));var rd=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/PC_Renderer.asset"));var sr=new SerializedObject(rd);sr.FindProperty("m_RenderingMode").intValue=mode;sr.ApplyModifiedPropertiesWithoutUndo();var sp=new SerializedObject(rp);sp.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue=rd;sp.FindProperty("m_AdditionalLightsRenderingMode").intValue=1;sp.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
   foreach(string lighting in new[]{"off","point","spot","shadow","day"}){sun.enabled=lighting=="day";local.enabled=lighting!="off"&&lighting!="day";local.type=lighting=="spot"?LightType.Spot:LightType.Point;local.shadows=lighting=="shadow"?LightShadows.Hard:LightShadows.None;blocker.SetActive(lighting=="shadow");float[] mean=new float[2];byte[][] pixels=new byte[2][];
    for(int stage=0;stage<2;stage++){foreach(var o in objects){var renderer=o.GetComponent<Renderer>();var old=renderer.sharedMaterial;var m=new Material(old);m.shader=Shader.Find(stage==0?"Review/FibreBefore116":"MapSharedProps/FibreProp");renderer.sharedMaterial=m;if(old.name.StartsWith("diagnostic"))UnityEngine.Object.DestroyImmediate(old);m.name="diagnostic";}
     var im=Fibre116Review.Image(camera,640,480);pixels[stage]=im.EncodeToPNG();var colours=im.GetPixels();mean[stage]=colours.Sum(c=>(c.r+c.g+c.b)/3)/colours.Length;File.WriteAllBytes(Path.Combine(output,"mode"+mode+"-"+lighting+"-"+(stage==0?"before":"after")+".png"),pixels[stage]);UnityEngine.Object.DestroyImmediate(im);foreach(var o in objects)Check(!ShaderUtil.ShaderHasError(o.GetComponent<Renderer>().sharedMaterial.shader),"shader compile");}
    if(lighting=="off"||lighting=="day")Check(pixels[0].SequenceEqual(pixels[1]),"no-local pixel exact "+mode+" "+lighting);if(lighting=="point"||lighting=="spot")Check(mean[1]>mean[0]+.005f,"local response "+mode+" "+lighting);rows.Add(new Row{mode=mode.ToString(),light=lighting,before=mean[0],after=mean[1]});}
   Check(rows.Last(x=>x.mode==mode.ToString()&&x.light=="shadow").after<rows.Last(x=>x.mode==mode.ToString()&&x.light=="point").after*.65f,"local shadow attenuation");
  }
  AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(output,"checks.json"),JsonUtility.ToJson(new Report{pass=true,prefabs=44,rows=rows.ToArray(),limits=new[]{"Source reader unchanged; old binary not run","Offscreen Editor only; Player/mobile not run"}},true));
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
